import{_ as a,o as n,c as e,a2 as s}from"./chunks/framework.A5mep7Fe.js";const g=JSON.parse('{"title":"🤖 03 · Agent 工程实践（动手篇）","description":"","frontmatter":{},"headers":[],"relativePath":"08-AI应用开发/03-Agent工程实践.md","filePath":"08-AI应用开发/03-Agent工程实践.md","lastUpdated":1786806808000}'),l={name:"08-AI应用开发/03-Agent工程实践.md"};function o(r,t,i,p,d,c){return n(),e("div",null,[...t[0]||(t[0]=[s(`<h1 id="🤖-03-·-agent-工程实践-动手篇" tabindex="-1">🤖 03 · Agent 工程实践（动手篇） <a class="header-anchor" href="#🤖-03-·-agent-工程实践-动手篇" aria-label="Permalink to &quot;🤖 03 · Agent 工程实践（动手篇）&quot;">​</a></h1><blockquote><p>从 0 搭一个生产可用的 Agent。原理见 <code>03-AI Agent</code>，本篇侧重「可运行的工程实现」与避坑。</p></blockquote><hr><h2 id="一、最小可用-agent-mvp" tabindex="-1">一、最小可用 Agent（MVP） <a class="header-anchor" href="#一、最小可用-agent-mvp" aria-label="Permalink to &quot;一、最小可用 Agent（MVP）&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 定义工具（函数 + JSON Schema 描述）</span></span>
<span class="line"><span>2. 主循环：</span></span>
<span class="line"><span>   - 把 system + 历史 + 工具描述 + 用户输入 给 LLM</span></span>
<span class="line"><span>   - 解析 LLM 输出：要么 Final Answer，要么 tool_call</span></span>
<span class="line"><span>   - 执行工具 → 结果回灌 → 继续循环</span></span>
<span class="line"><span>   - 达最大步数或得到答案则结束</span></span>
<span class="line"><span>3. 加记忆（短期窗口 + 长期向量检索）</span></span>
<span class="line"><span>4. 加可观测（记录每步轨迹）</span></span></code></pre></div><p><strong>核心循环不过 50 行代码</strong>——别被框架吓到。</p><h2 id="二、工程化关键点-生产必做" tabindex="-1">二、工程化关键点（生产必做） <a class="header-anchor" href="#二、工程化关键点-生产必做" aria-label="Permalink to &quot;二、工程化关键点（生产必做）&quot;">​</a></h2><ul><li><strong>流式</strong>：边思考边把中间过程/最终答案推前端（SSE）</li><li><strong>中断/取消</strong>：用户可中止长任务</li><li><strong>工具安全</strong>：危险操作确认、权限、超时、资源限制</li><li><strong>错误恢复</strong>：工具失败 → 错误回灌模型自我修正 → 重试/降级</li><li><strong>上下文管理</strong>：长对话摘要压缩、只留相关记忆</li><li><strong>模型路由</strong>：简单任务小模型，复杂才上大模型</li></ul><h2 id="三、常见失败模式与对策" tabindex="-1">三、常见失败模式与对策 <a class="header-anchor" href="#三、常见失败模式与对策" aria-label="Permalink to &quot;三、常见失败模式与对策&quot;">​</a></h2><table tabindex="0"><thead><tr><th>失败</th><th>对策</th></tr></thead><tbody><tr><td>循环打转</td><td>最大步数、循环检测、把关键结果写记忆</td></tr><tr><td>工具参数错</td><td>schema 校验 + 类型转换 + 示例</td></tr><tr><td>幻觉工具名</td><td>工具描述清晰 + 候选过滤</td></tr><tr><td>上下文爆</td><td>摘要压缩 + 检索式记忆</td></tr><tr><td>成本失控</td><td>模型路由 + 缓存 + 步数限制</td></tr></tbody></table><h2 id="四、可观测与评测" tabindex="-1">四、可观测与评测 <a class="header-anchor" href="#四、可观测与评测" aria-label="Permalink to &quot;四、可观测与评测&quot;">​</a></h2><ul><li>全链路 trace（每步 thought/action/observation/token/耗时）</li><li>固化任务集做回归（改 Prompt/模型后跑评测）</li><li>LLM-as-Judge 评最终质量 + 成功率指标</li></ul><h2 id="五、高频追问" tabindex="-1">五、高频追问 <a class="header-anchor" href="#五、高频追问" aria-label="Permalink to &quot;五、高频追问&quot;">​</a></h2><p><strong>Q1：自研核心循环还是用框架？</strong></p><blockquote><p>原型用框架快；生产多数场景自研核心循环（ReAct 不过几十行）更可控、好调试、成本低。框架适合快速验证或复杂组件复用。</p></blockquote><p><strong>Q2：Agent 上线最大的风险？</strong></p><blockquote><p>不可控性（长链路任一环失败/幻觉）、成本难预测、难评测。靠降级 + 全链路追踪 + 回归评测 + 成本监控化解。</p></blockquote><hr><p>➡️ 下一步：<a href="./04-MLOps与LLMOps">04-MLOps与LLMOps</a></p>`,19)])])}const u=a(l,[["render",o]]);export{g as __pageData,u as default};
